templates.app/blog/[id]/page.tsx:
import { notFound } from 'next/navigation'
import Link from 'next/link'

type Post = { id: number; title: string; body: string }

const posts: Record<number, Post> = {
  1: { id: 1, title: 'First Post', body: 'Hello from the blog!' },
  2: { id: 2, title: 'Second Post', body: 'More content here.' },
}

export default function BlogPost({ params }: { params: { id: string } }) {
  const post = posts[Number(params.id)]
  if (!post) {
    notFound()
  }
  return (
    <main className="min-h-screen p-8">
      <h1 className="text-4xl font-bold">{post.title}</h1>
      <p className="mt-4 text-gray-600">{post.body}</p>
      <Link href="/" className="mt-6 inline-block text-blue-600 underline">Back Home</Link>
    </main>
  )
}

